	CONSTRAINT fk_group_chats_group_id_groups FOREIGN KEY(group_id) REFERENCES groups (id),
	CONSTRAINT uq_group_chats_chat_id UNIQUE (chat_id),
	CONSTRAINT fk_group_chats_last_sender_users FOREIGN KEY(last_sender) REFERENCES users (id)
);

CREATE TABLE handles (
	handle VARCHAR(255) NOT NULL,
	user_id VARCHAR(36) NOT NULL,
	display_name VARCHAR(255) NOT NULL,
	created_at TIMESTAMP WITH TIME ZONE NOT NULL,
	CONSTRAINT pk_handles PRIMARY KEY (handle),
	CONSTRAINT fk_handles_user_id_users FOREIGN KEY(user_id) REFERENCES users (id)
);

CREATE INDEX ix_handles_user_id ON handles (user_id);

CREATE TABLE onboarding_state (
	user_id VARCHAR(36) NOT NULL,
